/* BIGAPP.AOU - R9 proof: an application larger than the R8 224 KiB limit.
 *
 * Image (slot 1): about 64 KiB of initialized data (table, generated by
 * gen_table.py), 400 KiB of BSS (work), and the code.  Text + data + BSS is
 * about 470 KiB, so the R8 loader (224 KiB) would refuse it.
 *
 * Checks: argc and argv; every table byte; the BSS is zero on entry, then a
 * full write and verify; a 300 KiB malloc with a pattern check; the heap free
 * count returns to its start.  It prints the R9 pass line only then. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "qdos386.h"

#define WORK_SIZE 409600u

extern unsigned char table[65536];
static unsigned char work[WORK_SIZE];

int main(int argc, char **argv)
{
	unsigned long i;
	unsigned int fails = 0;
	unsigned int free0, free1;
	unsigned char *big;

	unsigned long t0 = qd_ticks();

	printf("BIGAPP: argc = %d\n", argc);
	if (argc != 3 || strcmp(argv[0], "BIGAPP.AOU") != 0 ||
	    strcmp(argv[1], "one") != 0 || strcmp(argv[2], "two words") != 0)
		fails++;

	for (i = 0; i < 65536UL; i++)
		if (table[i] != (unsigned char) ((i * 7UL + 3UL) & 255UL)) {
			fails++;
			break;
		}
	printf("BIGAPP: table of 65536 bytes %s\n", fails == 0 ? "ok" : "BAD");

	for (i = 0; i < WORK_SIZE; i++)
		if (work[i] != 0) {
			fails++;
			break;
		}
	printf("BIGAPP: BSS of %u bytes zero on entry\n", WORK_SIZE);
	for (i = 0; i < WORK_SIZE; i++)
		work[i] = (unsigned char) ((i * 13UL + 5UL) & 255UL);
	for (i = 0; i < WORK_SIZE; i++)
		if (work[i] != (unsigned char) ((i * 13UL + 5UL) & 255UL)) {
			fails++;
			break;
		}

	free0 = qd_free_bytes();
	big = (unsigned char *) malloc(300u * 1024u);
	if (big == NULL) {
		fails++;
	} else {
		for (i = 0; i < 300UL * 1024UL; i++)
			big[i] = (unsigned char) (i ^ (i >> 8));
		for (i = 0; i < 300UL * 1024UL; i++)
			if (big[i] != (unsigned char) (i ^ (i >> 8))) {
				fails++;
				break;
			}
		free(big);
	}
	free1 = qd_free_bytes();
	if (free1 != free0)
		fails++;
	printf("BIGAPP: 300 KiB malloc and free, heap restored: %s\n",
	       free1 == free0 ? "yes" : "no");

	/* The timer kept running while the work above was done (the job is
	 * preempted by ticks, so the count must have moved). */
	if (qd_ticks() == t0)
		fails++;
	printf("BIGAPP: timer ticks advanced during the work: %s\n",
	       qd_ticks() != t0 ? "yes" : "no");

	if (fails == 0) {
		printf("QDOS/386 R9 LIBC + LARGE APP PASS\n");
		return 0;
	}
	printf("QDOS/386 R9 LARGE APP FAIL (%u)\n", fails);
	return 100 + fails;
}
